<template><div class="manage-page"><div class="page-header-row"><div><span class="eyebrow">অ্যাডমিন সেটআপ</span><h1>একাডেমিক সেটআপ</h1><p>শ্রেণি, সেকশন ও বিষয় তৈরি ও পরিচালনা করুন</p></div></div><div class="tabs"><button v-for="tab in tabs" :key="tab.value" :class="{active:active===tab.value}" @click="active=tab.value">{{tab.label}}</button></div><div class="manage-layout"><form class="card form-card" @submit.prevent="create"><h2>{{ currentLabel }} যোগ করুন</h2><div v-if="error" class="alert alert-error">{{error}}</div><div class="form-group"><label>বাংলা নাম *</label><input v-model="form.name_bn" class="form-control" required /></div><div class="form-group"><label>ইংরেজি নাম</label><input v-model="form.name_en" class="form-control" /></div><div v-if="active==='classes'" class="form-group"><label>গ্রেড লেভেল</label><input v-model.number="form.grade_level" type="number" class="form-control" /></div><div v-if="active==='classes'" class="form-group"><label>ধরন</label><input v-model="form.class_type" class="form-control" placeholder="regular" /></div><div v-if="active==='sections'" class="form-group"><label>শ্রেণি</label><select v-model="form.class_id" class="form-control"><option value="">শ্রেণি নির্বাচন করুন</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.name_bn}}</option></select></div><div v-if="active==='subjects'" class="form-group"><label>কোড</label><input v-model="form.code" class="form-control" /></div><div v-if="active==='subjects'" class="form-group"><label>বিষয়ের ধরন</label><input v-model="form.subject_type" class="form-control" placeholder="regular" /></div><button class="btn btn-primary btn-block" :disabled="saving">{{saving?'সংরক্ষণ হচ্ছে...':'যোগ করুন'}}</button></form><section class="card list-card"><div class="list-heading"><div><h2>{{currentLabel}} তালিকা</h2><p>{{items.length}}টি রেকর্ড</p></div><button class="btn btn-outline btn-sm" @click="load">রিফ্রেশ</button></div><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else class="managed-list"><div v-for="item in items" :key="item.id" class="managed-item"><div><b>{{item.name_bn}}</b><small>{{item.name_en||item.class_type||item.subject_type||''}}</small></div><span class="item-meta">{{active==='sections'?className(item.class_id):active==='subjects'?(item.code||'কোড নেই'):`গ্রেড ${item.grade_level||'—'}`}}</span><button class="delete-btn" title="মুছে ফেলুন" @click="remove(item.id)"><icon name="delete" /></button></div><div v-if="!items.length" class="empty-inline">কোনো রেকর্ড নেই</div></div></section></div></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const tabs=[{value:'classes',label:'শ্রেণি'},{value:'sections',label:'সেকশন'},{value:'subjects',label:'বিষয়'}];const active=ref('classes');const items=ref<any[]>([]);const classes=ref<any[]>([]);const loading=ref(true);const saving=ref(false);const error=ref('');const form=reactive<any>({name_bn:'',name_en:'',grade_level:0,class_type:'regular',class_id:'',code:'',subject_type:'regular'});const currentLabel=computed(()=>tabs.find(t=>t.value===active.value)?.label||'রেকর্ড');const endpoint=computed(()=>`/academic/${active.value}`);async function load(){loading.value=true;try{const r=await api.get(endpoint.value);items.value=r.data?.data||[];if(active.value==='classes')classes.value=items.value}catch(e){console.error(e)}finally{loading.value=false}}async function create(){saving.value=true;error.value='';try{const payload:any={name_bn:form.name_bn,name_en:form.name_en};if(active.value==='classes')Object.assign(payload,{grade_level:form.grade_level,class_type:form.class_type});if(active.value==='sections')payload.class_id=form.class_id||null;if(active.value==='subjects')Object.assign(payload,{code:form.code,subject_type:form.subject_type});await api.post(endpoint.value,payload);form.name_bn='';form.name_en='';await load()}catch(e:any){error.value=e?.response?.data?.message||'রেকর্ড তৈরি করা যায়নি'}finally{saving.value=false}}async function remove(id:number){if(!confirm(`${currentLabel.value} মুছে ফেলবেন?`))return;try{await api.delete(`${endpoint.value}/${id}`);await load()}catch(e){console.error(e)}}function className(id:number){return classes.value.find(c=>c.id===id)?.name_bn||'শ্রেণি নেই'}watch(active,load);onMounted(async()=>{await load();const r=await api.get('/academic/classes');classes.value=r.data?.data||[]})</script>
<style scoped>.manage-page{max-width:1300px;margin:0 auto;padding-bottom:2rem}.page-header-row{margin-bottom:1.2rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.tabs{display:flex;gap:.3rem;width:max-content;margin-bottom:1rem;padding:.25rem;background:#fff;border:1px solid var(--color-border-light);border-radius:12px}.tabs button{padding:.55rem 1rem;border:0;border-radius:9px;background:transparent;color:var(--color-text-light);font:.78rem var(--font-bn);cursor:pointer}.tabs button.active{color:#fff;background:var(--color-primary)}.manage-layout{display:grid;grid-template-columns:320px 1fr;gap:1rem}.card{background:#fff;border:1px solid var(--color-border-light);border-radius:17px;box-shadow:var(--shadow-sm)}.form-card{padding:1.2rem;height:max-content}.form-card h2,.list-heading h2{font:700 1rem var(--font-bn)}.form-group{margin-top:1rem}.form-group label{display:block;margin-bottom:.3rem;font:600 .78rem var(--font-bn)}.list-card{min-height:350px;padding:1.2rem}.list-heading{display:flex;justify-content:space-between;align-items:center;padding-bottom:.9rem;border-bottom:1px solid var(--color-border-light)}.list-heading p{margin-top:.2rem;color:var(--color-text-muted);font:.72rem var(--font-bn)}.managed-list{display:grid}.managed-item{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:.7rem;padding:.75rem .2rem;border-bottom:1px solid var(--color-border-light)}.managed-item b,.managed-item small{display:block}.managed-item b{font:.82rem var(--font-bn)}.managed-item small{margin-top:.12rem;color:var(--color-text-muted);font:.68rem var(--font-bn)}.item-meta{color:var(--color-text-light);font:.7rem var(--font-bn)}.delete-btn{display:grid;place-items:center;width:28px;height:28px;border:0;border-radius:8px;color:var(--color-error);background:var(--color-error-bg);cursor:pointer}.empty-inline{padding:3rem;text-align:center;color:var(--color-text-muted);font:.8rem var(--font-bn)}@media(max-width:800px){.manage-layout{grid-template-columns:1fr}}@media(max-width:500px){.tabs{width:100%}.tabs button{flex:1}}
</style>
